import React from 'react';
import './FaceRecognition.css';

const FaceRecognition = ({ imageUrl, box, onImageLoaded }) => {
  const hasBox = box.topRow !== undefined;

  return (
    <div className='fr-container'>
      {imageUrl && (
        <div className='fr-image-wrap'>
          <img
            id='inputimage'
            className='fr-image'
            alt='detected face'
            src={imageUrl}
            crossOrigin='anonymous'
            onLoad={onImageLoaded}
          />
          {hasBox && (
            <div
              className='fr-bounding-box'
              style={{
                top: box.topRow,
                right: box.rightCol,
                bottom: box.bottomRow,
                left: box.leftCol
              }}
            >
              <div className='fr-corner fr-corner-tl'></div>
              <div className='fr-corner fr-corner-tr'></div>
              <div className='fr-corner fr-corner-bl'></div>
              <div className='fr-corner fr-corner-br'></div>
              <div className='fr-label'>Face Detected</div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default FaceRecognition;
